import{_ as a,o as e,c as n,a2 as p}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"搭建集群","description":"","frontmatter":{},"headers":[],"relativePath":"kubernetes/create-cluster.md","filePath":"kubernetes/create-cluster.md","lastUpdated":1781086744000}'),t={name:"kubernetes/create-cluster.md"};function l(i,s,o,c,d,r){return e(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="搭建集群" tabindex="-1">搭建集群 <a class="header-anchor" href="#搭建集群" aria-label="Permalink to &quot;搭建集群&quot;">​</a></h1><p>Kubernetes是如今最为火热的容器编排软件，是谷歌严格保密十几年的秘密武器Borg的开源版本。初学者部署Kubernetes集群，建议从以下两个方面入手：</p><ol><li>Minikube。Minikube是Kubernetes官方提供的单节点小型集群，可以轻松跑在普通的笔记本电脑上。Minikube其实就是一个虚拟机，用户可以根据<a href="https://kubernetes.io/docs/setup/learning-environment/minikube/" target="_blank" rel="noreferrer">官方指南</a>进行安装。但是Minikube运行在虚拟机之上，性能有限，并且只支持单节点。如果你拥有超过一台的服务器可以使用，那么建议使用第二种方法。</li><li>使用kubeadm部署高可用集群。kubeadm是官方提供的快速部署Kubernetes集群的工具，目前总体上已经达到GA水平，基本满足生产使用，对于学习使用那更是绰绰有余。接下来对kubeadm部署集群的步骤进行详细地指南。</li></ol><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><p>CPU和内存：双核，4GB以上。 操作系统：基于x86_64的各种Linux发行版，包括CentOS，Federa，Ubuntu等，但是内核要求在3.10及以上。这里我使用的是Centos7系统。 容器运行时：一般情况，使用Docker作为容器运行时。</p><h2 id="修改主机名和hosts文件" tabindex="-1">修改主机名和hosts文件 <a class="header-anchor" href="#修改主机名和hosts文件" aria-label="Permalink to &quot;修改主机名和hosts文件&quot;">​</a></h2><p>为了使机器之间能够相互通信，首先我们需要给机器提供合适的主机名，并且在hosts文件中添加相关映射。</p><h3 id="修改主机名" tabindex="-1">修改主机名 <a class="header-anchor" href="#修改主机名" aria-label="Permalink to &quot;修改主机名&quot;">​</a></h3><ol><li>首先修改主机名，centos中利用<code>hostname server01</code>可以修改主机名为server01；</li><li>然后打开<code>/etc/sysconfig/network</code>文件，写入<code>HOSTNAME=server01</code>。</li><li>然后重新进入服务器，查看名称是否改变。</li></ol><h3 id="修改hosts文件" tabindex="-1">修改hosts文件 <a class="header-anchor" href="#修改hosts文件" aria-label="Permalink to &quot;修改hosts文件&quot;">​</a></h3><p>进入每一台机器的<code>/etc/hosts</code>文件，添加所有映射关系。例如，现在我有两台机器，一台叫做master，IP地址为192.168.0.1，一台叫做node-1，IP地址为192.168.0.2，那么我需要添加以下内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>192.168.0.1 master</span></span>
<span class="line"><span>192.168.0.2 node-1</span></span></code></pre></div><p>为了检验映射关系是否添加成功，我们可以利用ping命令。在master中执行<code>ping node-1</code>，在node-1中执行<code>ping master</code>，如果能够ping通，说明成功。</p><h2 id="系统基本配置" tabindex="-1">系统基本配置 <a class="header-anchor" href="#系统基本配置" aria-label="Permalink to &quot;系统基本配置&quot;">​</a></h2><p>在每一台机器上执行以下命令</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 关闭系统交换空间使用。（每次重启机器时都需要关闭，否则kubelet启动会报错）</span></span>
<span class="line"><span>swapoff -a </span></span>
<span class="line"><span></span></span>
<span class="line"><span># 关闭防火墙</span></span>
<span class="line"><span>systemctl stop firewalld</span></span>
<span class="line"><span>systemctl disable firewalld</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 设置SELinux</span></span>
<span class="line"><span>setenforce 0</span></span>
<span class="line"><span>sed -i &#39;s/^SELINUX=enforcing$/SELINUX=permissive/&#39; /etc/selinux/config</span></span></code></pre></div><p>另外，一些Centos7用户报告了由于iptables被绕过而导致路由出错的问题，因此我们需要保证<code>net.bridge.bridge-nf-call-iptables</code>设置为1。具体来说，执行以下命令</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat &lt;&lt;EOF &gt;  /etc/sysctl.d/k8s.conf</span></span>
<span class="line"><span>net.bridge.bridge-nf-call-ip6tables = 1</span></span>
<span class="line"><span>net.bridge.bridge-nf-call-iptables = 1</span></span>
<span class="line"><span>EOF</span></span>
<span class="line"><span>sysctl --system</span></span></code></pre></div><p>为了保证<code>br_netfilter</code>模块加载，我们需要执行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>modprobe br_netfilter</span></span></code></pre></div><h2 id="安装docker" tabindex="-1">安装Docker <a class="header-anchor" href="#安装docker" aria-label="Permalink to &quot;安装Docker&quot;">​</a></h2><p>如果没有安装过Docker，首先需要安装Docker作为容器运行时。</p><p>首先，尝试卸载旧版本的Docker，保证安装环境</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yum remove docker \\</span></span>
<span class="line"><span>                  docker-client \\</span></span>
<span class="line"><span>                  docker-client-latest \\</span></span>
<span class="line"><span>                  docker-common \\</span></span>
<span class="line"><span>                  docker-latest \\</span></span>
<span class="line"><span>                  docker-latest-logrotate \\</span></span>
<span class="line"><span>                  docker-logrotate \\</span></span>
<span class="line"><span>                  docker-engine</span></span></code></pre></div><p>然后安装相关依赖包 <code>yum install -y yum-utils device-mapper-persistent-data lvm2</code></p><p>然后将docker仓库添加到yum的源中</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yum-config-manager \\</span></span>
<span class="line"><span>    --add-repo \\</span></span>
<span class="line"><span>    https://download.docker.com/linux/centos/docker-ce.repo</span></span></code></pre></div><p>然后安装相应版本的Docker。这里我没有说最新版本，因为kubernetes往往没有来得及支持最新版本的Docker，所以在官网会推荐相应的版本，可以从<a href="https://kubernetes.io/docs/setup/production-environment/container-runtimes/" target="_blank" rel="noreferrer">这里</a>查看。这里我安装的是最新的Kubernetes v1.15.0，官网推荐的Docker版本是docker-ce-18.06.2.ce，于是我用以下命令安装docker-ce-18.06.2.ce</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yum update &amp;&amp; yum install docker-ce-18.06.2.ce</span></span></code></pre></div><p>安装完毕后，使用<code>systemctl start docker</code>来运行docker。然后我们可以用<code>docker version</code>命令查看是否成功安装，如果出现Client和Server两个版本信息，说明Docker已经成功安装并且运行。（如果只有Client的信息，说明docker没有成功运行，需要用<code>systemctl status docker</code>查看相关信息，寻找错误原因）。</p><h2 id="安装kubeadm-kubelet和kubectl" tabindex="-1">安装kubeadm，kubelet和kubectl <a class="header-anchor" href="#安装kubeadm-kubelet和kubectl" aria-label="Permalink to &quot;安装kubeadm，kubelet和kubectl&quot;">​</a></h2><ul><li><code>kubeadm</code>：快速创建集群的工具</li><li><code>kubelet</code>：这是一个需要在所有集群中机器上安装的组件，它用于执行开启Pod和容器等操作。</li><li><code>kubectl</code>：与集群通信的命令行工具，官方提供的CLI。</li></ul><p>首先要在yum中添加Kubernetes的仓库源。官方源的地址为<a href="https://packages.cloud.google.com/yum/repos/kubernetes-el7-x86_64%EF%BC%8C%E5%9C%A8%E5%9B%BD%E5%86%85%E6%97%A0%E6%B3%95%E8%AE%BF%E9%97%AE%EF%BC%8C%E6%89%80%E5%B9%B8%E9%98%BF%E9%87%8C%E4%BA%91%E4%B8%BA%E6%88%91%E4%BB%AC%E6%8F%90%E4%BE%9B%E4%BA%86%E9%95%9C%E5%83%8F%E6%BA%90%EF%BC%88%E6%84%9F%E8%B0%A2%E9%98%BF%E9%87%8C%E7%88%B8%E7%88%B8%EF%BC%89%EF%BC%8C%E4%BD%BF%E7%94%A8%E4%BB%A5%E4%B8%8B%E5%91%BD%E4%BB%A4%E6%B7%BB%E5%8A%A0%E9%98%BF%E9%87%8C%E9%95%9C%E5%83%8F%E6%BA%90" target="_blank" rel="noreferrer">https://packages.cloud.google.com/yum/repos/kubernetes-el7-x86_64，在国内无法访问，所幸阿里云为我们提供了镜像源（感谢阿里爸爸），使用以下命令添加阿里镜像源</a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat &lt;&lt;EOF &gt; /etc/yum.repos.d/kubernetes.repo</span></span>
<span class="line"><span>[kubernetes]</span></span>
<span class="line"><span>name=Kubernetes</span></span>
<span class="line"><span>baseurl=https://mirrors.aliyun.com/kubernetes/yum/repos/kubernetes-el7-x86_64/</span></span>
<span class="line"><span>enabled=1</span></span>
<span class="line"><span>gpgcheck=1</span></span>
<span class="line"><span>repo_gpgcheck=1</span></span>
<span class="line"><span>gpgkey=https://mirrors.aliyun.com/kubernetes/yum/doc/yum-key.gpg https://mirrors.aliyun.com/kubernetes/yum/doc/rpm-package-key.gpg</span></span>
<span class="line"><span>EOF</span></span></code></pre></div><p>然后运行yum install命令安装kubeadm和相关工具</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yum install -y kubelet kubeadm kubectl --disableexcludes=kubernetes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>systemctl enable --now kubelet</span></span></code></pre></div><h2 id="初始化主节点-master" tabindex="-1">初始化主节点（Master） <a class="header-anchor" href="#初始化主节点-master" aria-label="Permalink to &quot;初始化主节点（Master）&quot;">​</a></h2><p>成功安装kubeadm等一系列工具后，接下来就是正式部署Kubernetes集群了。首先我们需要在Master主机上执行<code>kubeadm init </code>相关命令，将Master节点配置成功，那么此时集群也就基本成功部署了。</p><p>具体来说，在master主机中执行以下命令</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubeadm init \\</span></span>
<span class="line"><span>	--image-repository=registry.aliyuncs.com/google_containers</span></span>
<span class="line"><span>	--pod-network-cidr=10.244.0.0/16</span></span></code></pre></div><p>其中<code>--imge-repository</code>指向阿里云的镜像仓库，显然还是因为google镜像仓库在国内无法访问；而<code>--pod-network-cidr</code>是为了接下来的Pod间网络通信使用flannel而设置的。如果你想安装其他的网络组件，可以在官网上<a href="https://kubernetes.io/docs/setup/production-environment/tools/kubeadm/create-cluster-kubeadm/#pod-network" target="_blank" rel="noreferrer">这里</a>查看所有支持的网络组件，并修改以上命令。</p><p>以上命令执行可能需要几分钟的时间。执行完毕后，主机点就基本上初始化成功了！</p><blockquote><p>如果初始化失败的话，根据提示寻找原因。第一次我初始化失败后，发现可能是由于在安装kubeadm之后才修改的主机名，造成kubeadm某些配置不正确。这种情况只需卸载并重新安装kubeadm，再次运行kubeadm init相关命令即可。 <code>$ kubeadm reset</code><code>$ yum remove kubeadm</code><code>$ yum install kubeadm --disableexcludes=kubernetes</code></p></blockquote><p>安装成功后，会显示一些重要信息。首先按照提示执行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir -p $HOME/.kube</span></span>
<span class="line"><span>sudo cp -i /etc/kubernetes/admin.conf $HOME/.kube/config</span></span>
<span class="line"><span>sudo chown $(id -u):$(id -g) $HOME/.kube/config</span></span></code></pre></div><p>然后给集群安装一个Pod网络组件。这里我选择flannel组件，执行以下命令安装</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sysctl net.bridge.bridge-nf-call-iptables=1</span></span>
<span class="line"><span>kubectl apply -f https://raw.githubusercontent.com/coreos/flannel/62e44c867a2846fefb68bd5f178daf4da3095ccb/Documentation/kube-flannel.yml</span></span></code></pre></div><p>安装完毕后，执行<code>kubectl get nodes</code>命令，可以发现master的状态从NotReady变成了Ready。</p><p>默认情况下，集群不会在Master节点上部署Pod，这意味着你的集群至少需要两个节点才能正常工作。如果你想要允许集群在Master上部署Pod，可以执行以下命令，这样即使只有一台机器，你也可以正常使用集群</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl taint nodes --all node-role.kubernetes.io/master-</span></span></code></pre></div><p>另外，<code>kubeadm init</code>成功后会显示有关kubeadm join的命令，我们需要保存这个命令，以便后面为集群添加节点使用。</p><h2 id="加入工作节点" tabindex="-1">加入工作节点 <a class="header-anchor" href="#加入工作节点" aria-label="Permalink to &quot;加入工作节点&quot;">​</a></h2><p>首先仍然需要为工作节点安装docker，kubeadm等相关工具，具体步骤见上。然后执行上一步骤中保存的<code>kubeadm join</code>相关命令，就成功地将该节点添加进集群中了。</p><p>如果初始化时的token没有保存或者已经过期，可以在Master使用以下命令重新生成<code>kubeadm join</code>相关token及命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubeadm token create --print-join-command</span></span></code></pre></div><h2 id="验证集群是否安装完成" tabindex="-1">验证集群是否安装完成 <a class="header-anchor" href="#验证集群是否安装完成" aria-label="Permalink to &quot;验证集群是否安装完成&quot;">​</a></h2><p>执行以下命令，验证集群相关Pod是否都正常创建并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl get pods --all-namespaces</span></span></code></pre></div><p>如果所有Pod都处于Running状态，说明集群正常运行。如果发现有状态错误的Pod，执行<code>kubectl describe pod &lt;pod_name&gt; --namespace=kube-system</code>查看错误原因，常见的错误一般是镜像没有下载完成。</p><p>至此，我们就通过<code>kubeadm</code>工具实现了Kubernetes集群的快速搭建。接下来可以愉快地使用了！</p><h2 id="踩过的坑" tabindex="-1">踩过的坑 <a class="header-anchor" href="#踩过的坑" aria-label="Permalink to &quot;踩过的坑&quot;">​</a></h2><h3 id="cgroup不支持pids子系统。" tabindex="-1">Cgroup不支持pids子系统。 <a class="header-anchor" href="#cgroup不支持pids子系统。" aria-label="Permalink to &quot;Cgroup不支持pids子系统。&quot;">​</a></h3><p>工作节点加入后，一直是NotReady状态。describe后发现报错如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Warning  FailedNodeAllocatableEnforcement  &lt;invalid&gt; (x1411 over 23h)     </span></span>
<span class="line"><span>kubelet, lbw-node-3   </span></span>
<span class="line"><span>Failed to update Node Allocatable Limits [&quot;kubepods&quot;]: failed to set supported cgroup subsystems for cgroup [kubepods]: Failed to find subsystem mount for required subsystem: pids</span></span></code></pre></div><p>由错误日志可知是节点中的Cgroup不支持子系统pids所致。于是用<code>uname -r</code>查看内核版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@localhost ~]# uname -r </span></span>
<span class="line"><span>3.10.0-327.el7.x86_64</span></span></code></pre></div><p>然后查看该内核所支持的CGROUP，发现的确不支持PIDS。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@localhost ~]# cat /boot/config-3.10.0-327.el7.x86_64  | grep CGROUP</span></span>
<span class="line"><span>CONFIG_CGROUPS=y</span></span>
<span class="line"><span># CONFIG_CGROUP_DEBUG is not set</span></span>
<span class="line"><span>CONFIG_CGROUP_FREEZER=y</span></span>
<span class="line"><span>CONFIG_CGROUP_DEVICE=y</span></span>
<span class="line"><span>CONFIG_CGROUP_CPUACCT=y</span></span>
<span class="line"><span>CONFIG_CGROUP_HUGETLB=y</span></span>
<span class="line"><span>CONFIG_CGROUP_PERF=y</span></span>
<span class="line"><span>CONFIG_CGROUP_SCHED=y</span></span>
<span class="line"><span>CONFIG_BLK_CGROUP=y</span></span>
<span class="line"><span># CONFIG_DEBUG_BLK_CGROUP is not set</span></span>
<span class="line"><span>CONFIG_NETFILTER_XT_MATCH_CGROUP=m</span></span>
<span class="line"><span>CONFIG_NET_CLS_CGROUP=y</span></span>
<span class="line"><span>CONFIG_NETPRIO_CGROUP=m</span></span></code></pre></div><p>然后在运行<code>yum update -y</code>后，使用<code> yum list kernel</code>命令查看当前安装的内核.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@lbw-master ~]# yum list kernel</span></span>
<span class="line"><span>Installed Packages</span></span>
<span class="line"><span>kernel.x86_64		3.10.0-327.el7			    @anaconda</span></span>
<span class="line"><span>kernel.x86_64		3.10.0-862.3.2.el7 		    @updates</span></span>
<span class="line"><span>kernel.x86_64		3.10.0-957.21.3.el7 	    @updates</span></span>
<span class="line"><span>kernel.x86_64		3.10.0-957.27.2.el7			@updates</span></span></code></pre></div><p>查看新版内核所支持的CGOURP</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@lbw-master ~]# cat /boot/config-3.10.0-957.27.2.el7.x86_64 | grep CGROUP</span></span>
<span class="line"><span>CONFIG_CGROUPS=y</span></span>
<span class="line"><span># CONFIG_CGROUP_DEBUG is not set</span></span>
<span class="line"><span>CONFIG_CGROUP_FREEZER=y</span></span>
<span class="line"><span>CONFIG_CGROUP_PIDS=y</span></span>
<span class="line"><span>CONFIG_CGROUP_DEVICE=y</span></span>
<span class="line"><span>CONFIG_CGROUP_CPUACCT=y</span></span>
<span class="line"><span>CONFIG_CGROUP_HUGETLB=y</span></span>
<span class="line"><span>CONFIG_CGROUP_PERF=y</span></span>
<span class="line"><span>CONFIG_CGROUP_SCHED=y</span></span>
<span class="line"><span>CONFIG_BLK_CGROUP=y</span></span>
<span class="line"><span># CONFIG_DEBUG_BLK_CGROUP is not set</span></span>
<span class="line"><span>CONFIG_NETFILTER_XT_MATCH_CGROUP=m</span></span>
<span class="line"><span>CONFIG_NET_CLS_CGROUP=y</span></span>
<span class="line"><span>CONFIG_NETPRIO_CGROUP=y</span></span></code></pre></div><p>发现的确有PIDS支持。于是接下来就是想办法将内核进行升级了。 用以下命令查看所有可用的内核</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@lbw-master ~]# awk -F\\&#39; &#39;$1==&quot;menuentry &quot; {print i++ &quot; : &quot; $2}&#39; /etc/grub2.cfg</span></span>
<span class="line"><span>0 : CentOS Linux (3.10.0-957.27.2.el7.x86_64) 7 (Core)</span></span>
<span class="line"><span>1 : CentOS Linux (3.10.0-957.21.3.el7.x86_64) 7 (Core)</span></span>
<span class="line"><span>2 : CentOS Linux (3.10.0-862.3.2.el7.x86_64) 7 (Core)</span></span>
<span class="line"><span>3 : CentOS Linux (3.10.0-327.el7.x86_64) 7 (Core)</span></span>
<span class="line"><span>4 : CentOS Linux (0-rescue-c4da2e677e384e85b9fd9f27eb3a9f8a) 7 (Core)</span></span></code></pre></div><p>用<code>grub2-set-default</code>命令设置默认启动内核。利用设为0表示使用上一个命令输出的第一个内核。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grub2-set-default 0</span></span></code></pre></div><p>然后用<code>grub2-mkconfig</code>命令生成配置文件并应用在grub.config文件中。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grub2-mkconfig -o /boot/grub2/grub.cfg</span></span></code></pre></div><p>执行完毕后，用<code>reboot</code>命令重启机器即可。</p>`,79)])])}const h=a(t,[["render",l]]);export{b as __pageData,h as default};
